CREATE EXTENSION IF NOT EXISTS pg_trgm;

CREATE TABLE IF NOT EXISTS item_categories (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, parent_id uuid, code text NOT NULL, name_ar text NOT NULL, name_en text, sort_order int NOT NULL DEFAULT 0, show_in_pos boolean NOT NULL DEFAULT true, show_in_sale boolean NOT NULL DEFAULT true, show_in_purch boolean NOT NULL DEFAULT true, kitchen_printer text, print_separately boolean NOT NULL DEFAULT false, branch_id uuid, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_at timestamptz, updated_by uuid, deleted_at timestamptz, deleted_by uuid, version int NOT NULL DEFAULT 1, legacy_source text, legacy_id text);
CREATE TABLE IF NOT EXISTS units_of_measure (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, code text NOT NULL, name_ar text NOT NULL, name_en text, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_at timestamptz, updated_by uuid, deleted_at timestamptz, deleted_by uuid, version int NOT NULL DEFAULT 1, legacy_source text, legacy_id text);
CREATE TABLE IF NOT EXISTS tax_groups (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, name_ar text NOT NULL, name_en text, rate numeric(7,4) NOT NULL CHECK(rate >= 0 AND rate <= 100), vat_account_id uuid, is_inclusive_default boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_at timestamptz, updated_by uuid, deleted_at timestamptz, deleted_by uuid, version int NOT NULL DEFAULT 1, legacy_source text, legacy_id text);
CREATE TABLE IF NOT EXISTS items (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, sku text NOT NULL, barcode text, name_ar text NOT NULL, name_en text, category_id uuid NOT NULL REFERENCES item_categories(id), base_unit_id uuid NOT NULL REFERENCES units_of_measure(id), kind text NOT NULL DEFAULT 'stock' CHECK(kind IN ('stock','service','composite')), sale_price numeric(20,4), purchase_price numeric(20,4), tax_group_id uuid REFERENCES tax_groups(id), min_qty numeric(20,4) NOT NULL DEFAULT 0, max_qty numeric(20,4), max_discount_pct numeric(7,4), max_discount_amt numeric(20,4), track_lot boolean NOT NULL DEFAULT false, track_serial boolean NOT NULL DEFAULT false, weighted_scale boolean NOT NULL DEFAULT false, show_in_pos boolean NOT NULL DEFAULT true, egy_item_code text, egy_code_type text, withholding_rate numeric(7,4), image_file_id uuid, kind_flags jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_at timestamptz, updated_by uuid, deleted_at timestamptz, deleted_by uuid, version int NOT NULL DEFAULT 1, legacy_source text, legacy_id text);
CREATE TABLE IF NOT EXISTS item_units (item_id uuid NOT NULL REFERENCES items(id) ON DELETE CASCADE, unit_id uuid NOT NULL REFERENCES units_of_measure(id), ratio numeric(20,6) NOT NULL CHECK(ratio > 0), barcode text, sale_price numeric(20,4), purchase_price numeric(20,4), is_default_purchase boolean NOT NULL DEFAULT false, is_default_sale boolean NOT NULL DEFAULT false, PRIMARY KEY(item_id,unit_id));
CREATE TABLE IF NOT EXISTS item_barcodes (tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, barcode text NOT NULL, item_id uuid NOT NULL REFERENCES items(id) ON DELETE CASCADE, unit_id uuid REFERENCES units_of_measure(id), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(tenant_id,barcode));
CREATE TABLE IF NOT EXISTS item_alternative_codes (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, item_id uuid NOT NULL REFERENCES items(id) ON DELETE CASCADE, code text NOT NULL, notes text, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_at timestamptz, updated_by uuid, deleted_at timestamptz, deleted_by uuid, version int NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS item_components (item_id uuid NOT NULL REFERENCES items(id) ON DELETE CASCADE, component_item_id uuid NOT NULL REFERENCES items(id), qty numeric(20,4) NOT NULL CHECK(qty > 0), unit_id uuid NOT NULL REFERENCES units_of_measure(id), kind text NOT NULL DEFAULT 'component', PRIMARY KEY(item_id,component_item_id), CHECK(item_id <> component_item_id));
CREATE TABLE IF NOT EXISTS item_price_history (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, item_id uuid NOT NULL REFERENCES items(id), unit_id uuid, prices jsonb NOT NULL, recorded_by uuid, recorded_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS item_details (item_id uuid PRIMARY KEY REFERENCES items(id) ON DELETE CASCADE, tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, supplier_ref text, importer text, net_weight numeric(20,4), lead_time text, notes text, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_at timestamptz, updated_by uuid, deleted_at timestamptz, deleted_by uuid, version int NOT NULL DEFAULT 1);
CREATE UNIQUE INDEX IF NOT EXISTS item_categories_tenant_code_key ON item_categories(tenant_id,code) WHERE deleted_at IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS units_of_measure_tenant_code_key ON units_of_measure(tenant_id,code) WHERE deleted_at IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS items_tenant_sku_key ON items(tenant_id,sku) WHERE deleted_at IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS item_alt_codes_tenant_code_key ON item_alternative_codes(tenant_id,code) WHERE deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS items_name_trgm_idx ON items USING gin ((name_ar || ' ' || coalesce(name_en,'')) gin_trgm_ops);
CREATE INDEX IF NOT EXISTS items_tenant_category_idx ON items(tenant_id,category_id);
CREATE INDEX IF NOT EXISTS items_tenant_barcode_idx ON items(tenant_id,barcode);
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['item_categories','units_of_measure','tax_groups','items','item_barcodes','item_alternative_codes','item_price_history','item_details'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t); EXECUTE format('DROP POLICY IF EXISTS tenant_isolation ON %I',t); EXECUTE format('CREATE POLICY tenant_isolation ON %I USING (tenant_id = current_setting(''app.tenant_id'', true)::uuid) WITH CHECK (tenant_id = current_setting(''app.tenant_id'', true)::uuid)',t); END LOOP; END $$;
ALTER TABLE item_units ENABLE ROW LEVEL SECURITY;
ALTER TABLE item_units FORCE ROW LEVEL SECURITY;
ALTER TABLE item_components ENABLE ROW LEVEL SECURITY;
ALTER TABLE item_components FORCE ROW LEVEL SECURITY;
ALTER TABLE price_list_items ADD COLUMN IF NOT EXISTS item_id uuid;
CREATE INDEX IF NOT EXISTS price_list_items_item_idx ON price_list_items(item_id);
